// ===== EDIT THESE =====
const BLOG_ID = 'YOUR_BLOG_ID';   // numeric Blogger blog ID
const PUBLISH_AS_DRAFT = true;    // keep true until you trust the output
// ======================
const topics = [
  "How a transistor works: from switch to logic gate",
  "What is Moore's Law, and is it ending?",
  "How silicon wafers are made",
  "Photolithography explained: how chips are printed with light",
  "CPU vs GPU vs NPU: what is the difference?",
  "What does a process node (7nm, 5nm, 3nm) really mean?",
  "SRAM vs DRAM vs NAND flash: how chip memory works",
  "Chiplets: why the industry is breaking chips into pieces",
  "How chips are tested and packaged",
  "RISC-V vs ARM vs x86: instruction set architectures",
  "Why semiconductors are so hard to manufacture",
  "How a CPU executes an instruction: fetch, decode, execute"
];
const sd = $getWorkflowStaticData('global');
const i = (sd.index ?? 0) % topics.length;
sd.index = i + 1;
return [{ json: { topic: topics[i], blogId: BLOG_ID, isDraft: PUBLISH_AS_DRAFT } }];

const cfg = $input.first().json;

const system = `You are an expert semiconductor educator writing for an educational blog called "Chip World".
Write for curious beginners and students: clear, accurate, friendly, no hype.
RULES:
- Only use facts and numbers you are confident are well established. Round figures and say "approximately".
- If a chart uses estimated or simplified data, say so in its caption (e.g. "illustrative values").
- Never invent studies, quotes, or URLs.
- Output ONLY one valid JSON object. No markdown fences, no commentary.`;

const user = `Write an educational blog article on: "${cfg.topic}"

Return JSON with exactly this shape:
{
  "title": "engaging but accurate title",
  "summary": "one-sentence summary",
  "labels": ["3-5 short tags"],
  "intro_html": "<p>...</p> 1-2 paragraphs",
  "sections": [
    { "heading": "...", "html": "<p>...</p> (may use <ul>, <ol>, <strong>, <table>)" }
  ],
  "charts": [
    { "type": "bar" or "line", "scale": "linear" or "log",
      "title": "...", "x_label": "...", "y_label": "...",
      "labels": ["category or year", ...], "values": [numbers],
      "caption": "what the chart shows + note if illustrative" }
  ],
  "diagram": { "title": "...", "steps": ["short step 1", "short step 2", ...], "caption": "..." },
  "key_takeaways": ["3-5 bullet strings"],
  "quiz": [ { "q": "question", "a": "answer" } ]
}

Requirements:
- 4 to 5 sections, about 800-1200 words total in the sections.
- 2 charts, each with 4 to 8 data points. Use scale "log" for quantities spanning many orders of magnitude (e.g. transistor counts).
- 1 process diagram with 4 to 7 short steps (under 60 characters each).
- 3 quiz questions.
- Define jargon the first time you use it.`;

return [{ json: { ...cfg, requestBody: {
  model: 'deepseek/deepseek-chat',   // swap for any free model
  messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
  temperature: 0.5,
  max_tokens: 6000
}}}];

const item = $input.first().json;

// Extract the model response.
let raw = item.text ?? item.output ?? item.response;

if (raw && typeof raw === 'object') {
  raw = raw.text ?? raw.output ?? raw.content;
}

if (typeof raw !== 'string' || !raw.trim()) {
  throw new Error(
    `Missing LLM text. Available fields: ${Object.keys(item).join(', ')}`
  );
}

// Remove optional Markdown fences.
raw = raw.trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/, '');

let article;

try {
  article = JSON.parse(raw);
} catch (e) {
  throw new Error(`Invalid LLM JSON: ${e.message}`);
}

if (!article.title) {
  throw new Error('The LLM response has no title.');
}

let sections = article.content ?? article.sections;

if (typeof sections === 'string') {
  sections = [{ section: 'Article', text: sections }];
}

if (!Array.isArray(sections) || sections.length === 0) {
  throw new Error(
    `Expected a nonempty content array. Found keys: ${
      Object.keys(article).join(', ')
    }`
  );
}

function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>"']/g, ch => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;'
  })[ch]);
}

const articleHtml = sections.map((section, index) => {
  if (typeof section === 'string') {
    return `<p>${escapeHtml(section).replace(/\n/g, '<br>')}</p>`;
  }

  const heading =
    section.section ?? section.heading ?? `Section ${index + 1}`;

  const body = section.text ?? section.content ?? '';

  const paragraphs = String(body)
    .split(/\n\s*\n/)
    .map(p => p.trim())
    .filter(Boolean)
    .map(p => `<p>${escapeHtml(p).replace(/\n/g, '<br>')}</p>`)
    .join('\n');

  return `<section>
    <h2>${escapeHtml(heading)}</h2>
    ${paragraphs}
  </section>`;
}).join('\n');

return [{
  json: {
    title: article.title,
    summary: article.summary ?? '',
    labels: Array.isArray(article.labels)
      ? article.labels
      : ['Semiconductors', 'Electronics'],
    articleHtml,
    status: 'ready_for_html'
  }
}];

const item = $input.first().json;

if (!item.title || !item.articleHtml) {
  throw new Error(
    'Missing title or articleHtml. Check Parse Article JSON output.'
  );
}

function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>"']/g, ch => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;'
  })[ch]);
}

const title = escapeHtml(item.title);
const summary = escapeHtml(item.summary);

const bloggerHtml = `
<div style="font-family:Arial,Helvetica,sans-serif;
max-width:850px;margin:auto;color:#263238;
line-height:1.8;font-size:17px;">

  <header style="background:#102a43;color:#fff;
  padding:24px;border-radius:12px;margin-bottom:24px;">
    <p style="color:#8ee3f5;font-size:13px;
    font-weight:bold;letter-spacing:2px;">
      CHIP WORLD · SEMICONDUCTOR EDUCATION
    </p>
    <h1 style="font-size:32px;line-height:1.25;
    color:#fff;">${title}</h1>
    <p style="color:#d9eaf2;">${summary}</p>
  </header>

  <article>
    ${item.articleHtml}
  </article>

  <footer style="margin-top:32px;padding-top:16px;
  border-top:1px solid #dce3e8;font-size:13px;
  color:#607d8b;">
    <p>Published for educational purposes by
    <strong>Chip World</strong>.</p>
  </footer>
</div>
`;

return [{
  json: {
    bloggerTitle: item.title,
    bloggerHtml,
    labels: item.labels ?? [],
    status: 'ready_for_blogger'
  }
}];

const item = $input.first().json;

return [{
  json: {
    ...item,
    blogId: "put_your_blog_id",
    isDraft: true
  }
}];
